al_status']?:$detail['sunat_status']);$detail_fiscal=sanitize_key($detail['fiscal_status']?:'not_sent'); ?><div class="spf-panel"><h2><?php echo esc_html($label($detail['document_type']).' '.$detail['serie'].'-'.$detail['correlative']); ?></h2><p><strong><?php esc_html_e('Venta:','sistema-para-farmacias'); ?></strong> <?php echo esc_html($detail['sale_number']); ?> · <strong><?php esc_html_e('Cliente:','sistema-para-farmacias'); ?></strong> <?php echo esc_html($detail['business_name']?:$detail['customer_name']?:'—'); ?> · <strong><?php esc_html_e('Total:','sistema-para-farmacias'); ?></strong> <?php echo esc_html(SPF_Config::money($detail['total'])); ?></p><p><strong><?php esc_html_e('Estado interno:','sistema-para-farmacias'); ?></strong> <?php echo esc_html($statuses[$detail_internal]??$detail_internal); ?> · <strong><?php esc_html_e('Estado fiscal:','sistema-para-farmacias'); ?></strong> <?php echo esc_html($fiscal_statuses[$detail_fiscal]??$detail_fiscal); ?></p><div class="spf-table-scroll"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Producto','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Cantidad','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Precio','sistema-para-farmacias'); ?></th><th><?php echo esc_html(SPF_Config::tax_name()); ?></th><th><?php esc_html_e('Total','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php foreach($detail_items as $item): ?><tr><td><?php echo esc_html($item['product_name']); ?></td><td><?php echo esc_html($item['quantity']); ?></td><td><?php echo esc_html(SPF_Config::money($item['unit_price'])); ?></td><td><?php echo esc_html(SPF_Config::money($item['igv'])); ?></td><td><?php echo esc_html(SPF_Config::money($item['total'])); ?></td></tr><?php endforeach; ?></tbody></table></div><p><strong><?php esc_html_e('Referencia interna:','sistema-para-farmacias'); ?></strong> <code><?php echo esc_html($detail['qr_data']); ?></code></p><?php if(in_array($detail_internal,['draft','ready'],true)): 